from pathlib import Path
import nbformat as nbf
ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'05_Starter'/'notebooks'/'phase2'; OUT.mkdir(parents=True,exist_ok=True)

def md(s): return nbf.v4.new_markdown_cell(s)
def code(s): return nbf.v4.new_code_cell(s)
notebooks=[
('07_payroll_data_audit.ipynb','Task 6A — Payroll data audit',[
('m', '# 07 · Payroll data audit\n\n**Purpose:** establish data quality before modeling. This notebook is deliberately label-blind. Do not load CX-06 labels until predictions are frozen.\n\nQuestions: key uniqueness, employee/run duplicates, missingness, negative/zero values, payroll arithmetic, time coverage, and plausible ranges.'),
('c', "from pathlib import Path\nimport sys, pandas as pd, numpy as np\nROOT = Path.cwd()\nwhile ROOT != ROOT.parent and not (ROOT/'03_Data'/'csv').exists(): ROOT = ROOT.parent\nif not (ROOT/'03_Data'/'csv').exists(): ROOT = Path('../../..').resolve()\nsys.path.insert(0, str(ROOT/'src'))\nfrom cortexhr.phase2.payroll import load_payroll, audit_payroll\nCSV = ROOT/'03_Data'/'csv'\ndf = load_payroll(CSV/'payroll_monthly_features.csv')\nprint('Shape:', df.shape, '| date range:', df.month.min(), 'to', df.month.max())\ndisplay(df.head())"),
('c', "audit = audit_payroll(df)\ndisplay(pd.Series(audit, name='count').to_frame())\ndisplay(df.isna().mean().sort_values(ascending=False).rename('missing_rate').to_frame())\ndisplay(df.describe(include='all').T)"),
('m', '## Interpretation checklist\n\n- Explain any duplicate key separately from multiple legitimate employees or payroll runs.\n- Check whether `gross_pay - total_deductions` approximately equals `net_pay`; use a tolerance for rounding.\n- Do not silently delete anomalous records. Record the finding and preserve source row IDs.\n- Missing CX-06 label file is a hard evaluation blocker, not permission to invent labels.'),
('c', "identity_error = (df.gross_pay - df.total_deductions - df.net_pay).abs()\nquality = pd.DataFrame({'check':['duplicate payroll item IDs','duplicate employee/run pairs','negative net pay','zero net pay','gross-net identity diff > 0.05'], 'count':[df.payroll_item_id.duplicated().sum(), df.duplicated(['employee_id','run_id']).sum(), (df.net_pay<0).sum(), (df.net_pay==0).sum(), (identity_error>0.05).sum()]})\ndisplay(quality)\nquality.to_csv(ROOT/'reports/phase2/payroll_data_quality.csv', index=False)"),
]),
('08_payroll_eda_features.ipynb','Task 6B — Payroll EDA and feature engineering',[
('m','# 08 · Payroll EDA and feature engineering\n\nExplore numeric distributions, time trends, role/department variation and financial identities before modeling. Ratio denominators are protected from zero; extreme ratios remain visible for review.'),
('c',"from pathlib import Path\nimport sys, pandas as pd, numpy as np, matplotlib.pyplot as plt\nROOT=Path.cwd()\nwhile ROOT != ROOT.parent and not (ROOT/'03_Data'/'csv').exists(): ROOT=ROOT.parent\nsys.path.insert(0,str(ROOT/'src'))\nfrom cortexhr.phase2.payroll import load_payroll, engineer_payroll_features, FEATURE_COLS\nCSV=ROOT/'03_Data'/'csv'; df=load_payroll(CSV/'payroll_monthly_features.csv'); feat=engineer_payroll_features(df)\ndisplay(feat[FEATURE_COLS].describe().T)"),
('c',"fig, ax=plt.subplots(figsize=(10,4)); df.groupby(df.month.dt.to_period('M')).net_pay.median().plot(ax=ax); ax.set_title('Median net pay by payroll month'); ax.set_xlabel('Month'); ax.set_ylabel('Median net pay'); plt.xticks(rotation=45); plt.tight_layout(); plt.show()\nfig, ax=plt.subplots(figsize=(7,4)); ax.hist(feat.gross_to_fixed_ratio.clip(upper=5), bins=40); ax.set_title('Gross / fixed-gross ratio (capped at 5 for visualization only)'); ax.set_xlabel('Ratio'); ax.set_ylabel('Rows'); plt.tight_layout(); plt.show()"),
('m','## Feature design notes\n\nThe model matrix intentionally excludes employee IDs, payroll IDs, run IDs, raw month strings, department labels and all error labels. Identifiers remain only for joining scored output back to source rows. `money_at_risk` is a review-priority proxy, not a validated loss estimate.'),
('c',"display(feat[['gross_to_fixed_ratio','deduction_ratio','net_to_gross_ratio','variable_to_fixed_ratio','lop_day_ratio','overtime_pay_ratio']].quantile([.01,.05,.5,.95,.99]).T)\nassert np.isfinite(feat[FEATURE_COLS].replace([np.inf,-np.inf],np.nan).select_dtypes('number').fillna(0).to_numpy()).all()"),
]),
('09_payroll_rules_baselines.ipynb','Task 6C — Transparent rules and baseline comparison',[
('m','# 09 · Transparent rules and baselines\n\nBuild auditable business rules before adding an unsupervised model. A rule firing is a review flag, not proof of fraud or employee wrongdoing.'),
('c',"from pathlib import Path\nimport sys,pandas as pd\nROOT=Path.cwd()\nwhile ROOT != ROOT.parent and not (ROOT/'03_Data'/'csv').exists(): ROOT=ROOT.parent\nsys.path.insert(0,str(ROOT/'src'))\nfrom cortexhr.phase2.payroll import load_payroll,payroll_rule_flags\nCSV=ROOT/'03_Data'/'csv'; df=load_payroll(CSV/'payroll_monthly_features.csv'); rules=payroll_rule_flags(df)\nrule_cols=[c for c in rules if c.isupper()]\ndisplay(rules[rule_cols].sum().sort_values(ascending=False).rename('rows_flagged').to_frame())\ndisplay(rules[rules.rule_flagged].head(20))"),
('m','## Baselines\n\nCompare (1) transparent rules, (2) Isolation Forest alone, and (3) their union. Use `anomaly_baselines.csv` only as the supplied historical benchmark; ensure the population, label definitions and flag thresholds match before treating values as directly comparable.'),
('c',"baseline_path=CSV/'anomaly_baselines.csv'\nif baseline_path.exists(): display(pd.read_csv(baseline_path))\nelse: print('No baseline file found; comparison is blocked until supplied.')"),
]),
('10_payroll_iforest_train_score.ipynb','Task 6D — Unsupervised detector',[
('m','# 10 · Isolation Forest training and frozen scoring\n\nThe fit function accepts payroll features only; it has no label parameter. Freeze scored outputs before opening the CX-06 validation labels. Set a reproducible seed and record contamination.'),
('c',"from pathlib import Path\nimport sys,pandas as pd\nROOT=Path.cwd()\nwhile ROOT != ROOT.parent and not (ROOT/'03_Data'/'csv').exists(): ROOT=ROOT.parent\nsys.path.insert(0,str(ROOT/'src'))\nfrom cortexhr.phase2.payroll import load_payroll,fit_isolation_forest,score_payroll\nCSV=ROOT/'03_Data'/'csv'; df=load_payroll(CSV/'payroll_monthly_features.csv')\nmodel=fit_isolation_forest(df, contamination=0.03, random_state=42)\npredictions,model=score_payroll(df, model=model)\ndisplay(predictions.head(20))\npredictions.to_csv(ROOT/'reports/phase2/payroll_predictions_frozen.csv',index=False)\nprint('Frozen predictions:',len(predictions),'| flagged:',int(predictions.flagged.sum()))"),
('m','## Label-leakage guard\n\nDo not fit, tune thresholds, select features, or modify the model using `unlock_CX-06`. Only after saving the frozen predictions may the authorized validation file be loaded for evaluation. If that file is unavailable, mark per-type evaluation **BLOCKED — validation labels not supplied**.'),
]),
('11_payroll_error_type_evaluation.ipynb','Task 6E — CX-06 per-type evaluation',[
('m','# 11 · Per-error-type evaluation against CX-06\n\nThis notebook expects the authorized validation file to be placed at `04_Validation_Vault/unlock_CX-06.csv` or the path supplied by the evaluator. The model must already be fit and predictions frozen. Never fabricate labels or report proxy metrics as ground truth.'),
('c',"from pathlib import Path\nimport pandas as pd\nROOT=Path.cwd()\nwhile ROOT != ROOT.parent and not (ROOT/'03_Data'/'csv').exists(): ROOT=ROOT.parent\npred_path=ROOT/'reports/phase2/payroll_predictions_frozen.csv'\nlabel_path=ROOT/'04_Validation_Vault/unlock_CX-06.csv'\nif not pred_path.exists(): raise FileNotFoundError('Run notebook 10 first to freeze predictions.')\npred=pd.read_csv(pred_path)\nif not label_path.exists():\n    print('BLOCKED: authorized unlock_CX-06.csv not present. Do not create or guess labels. Expected columns must be mapped from the supplied validation file.')\nelse:\n    labels=pd.read_csv(label_path); print('Available validation columns:',labels.columns.tolist()); display(labels.head())"),
('m','## Required reporting\n\nReport precision and recall for each of the eight official error types, plus support, TP, FP, FN. Add rule-only / Isolation Forest-only / combined comparison. A type absent from the validation file must be reported as unavailable, not silently omitted. Save evidence CSV and document label mapping.'),
]),
('12_anomaly_explanations_money_at_risk.ipynb','Task 7 — Explanations and money at risk',[
('m','# 12 · Explain flags and prioritize review\n\nCreate human-readable reason codes and texts; use the exact output schema required by `sample_anomaly_results.csv`. Sort flagged rows by money at risk, but explicitly state that the amount is a triage proxy unless finance validates the loss calculation.'),
('c',"from pathlib import Path\nimport pandas as pd\nROOT=Path.cwd()\nwhile ROOT != ROOT.parent and not (ROOT/'03_Data'/'csv').exists(): ROOT=ROOT.parent\npred=pd.read_csv(ROOT/'reports/phase2/payroll_predictions_frozen.csv')\nrequired=['result_id','source_dataset','record_id','employee_id','period','anomaly_score','flagged','reason_code','reason_text','money_at_risk','model_version','scored_at']\nout=pd.DataFrame({'result_id':['P2-'+str(i+1).zfill(5) for i in range(len(pred))], 'source_dataset':'payroll_monthly_features','record_id':pred.payroll_item_id,'employee_id':pred.employee_id,'period':pred.month,'anomaly_score':pred.anomaly_score,'flagged':pred.flagged.map({True:'Y',False:'N'}),'reason_code':pred.reason_code,'reason_text':pred.reason_text,'money_at_risk':pred.money_at_risk,'model_version':pred.model_version,'scored_at':pd.Timestamp.utcnow().isoformat()})\nout=out[required].sort_values(['flagged','money_at_risk'],ascending=[True,False])\ndisplay(out.head(20)); out.to_csv(ROOT/'reports/phase2/payroll_anomaly_explanations.csv',index=False)"),
('m','## Acceptance checks\n\n- All 12 columns match the sample schema and have stable types.\n- Reason codes are non-empty for flagged rows.\n- `money_at_risk` is numeric and sorted descending among flagged records.\n- Inspect at least 20 rows manually and document false-positive patterns.'),
('c',"assert list(out.columns)==required\nassert out.loc[out.flagged=='Y','reason_code'].notna().all()\nassert pd.to_numeric(out.money_at_risk,errors='coerce').notna().all()\nprint('Schema check passed. Flagged rows:',int((out.flagged=='Y').sum()))\ndisplay(out[out.flagged=='Y'].head(20))"),
]),
('13_api_smoke_and_validation.ipynb','Task 8 — API smoke checks',[
('m','# 13 · API contracts and validation\n\nStart the API in a terminal with `uvicorn app.main:app --app-dir 05_Starter/api_skeleton --reload`. Visit `/docs`, then run the tests. API model objects should be loaded once per process, not refit for every request.'),
('c',"from pathlib import Path\nimport sys\nROOT=Path.cwd()\nwhile ROOT != ROOT.parent and not (ROOT/'03_Data'/'csv').exists(): ROOT=ROOT.parent\nprint('Run from repository root:')\nprint('uvicorn app.main:app --app-dir 05_Starter/api_skeleton --reload')\nprint('Then open http://127.0.0.1:8000/docs')\nprint('Automated tests: pytest -q tests_phase2')"),
('m','## Manual API cases\n\n1. `GET /v1/health` returns 200.\n2. Valid attendance request returns a stable response schema.\n3. `present_days > scheduled_days` returns 422.\n4. Valid payroll row is scored and has reason fields.\n5. Malformed payroll numbers return 422.\n6. `POST /v1/chat` returns intent, confidence, reply and slots.\n7. Empty message is rejected at schema validation.\n8. Model training is not repeated per request.'),
]),
('14_chatbot_nlu_workflow.ipynb','Task 9 — Chatbot NLU full workflow',[
('m','# 14 · Chatbot NLU: audit → train → evaluate\n\nOfficial data contains 858 training examples across 33 intents and a separate test set. Treat the provided test set as evaluation-only; do not merge it into training. Baseline is TF-IDF + Logistic Regression with reproducible settings.'),
('c',"from pathlib import Path\nimport sys,pandas as pd, numpy as np\nfrom sklearn.metrics import ConfusionMatrixDisplay\nimport matplotlib.pyplot as plt\nROOT=Path.cwd()\nwhile ROOT != ROOT.parent and not (ROOT/'03_Data'/'csv').exists(): ROOT=ROOT.parent\nsys.path.insert(0,str(ROOT/'src'))\nfrom cortexhr.phase2.chatbot import train_intent_model,evaluate_intent_model\nCSV=ROOT/'03_Data'/'csv'; train=pd.read_csv(CSV/'chatbot_nlu_training.csv'); test=pd.read_csv(CSV/'chatbot_test_set.csv')\nprint('Training shape:',train.shape,'| intents:',train.intent.nunique(),'| test shape:',test.shape)\ndisplay(train.isna().sum().rename('missing').to_frame()); display(train.intent.value_counts().rename('examples').to_frame())\nassert len(train)==858 and train.intent.nunique()==33"),
('c',"model=train_intent_model(CSV/'chatbot_nlu_training.csv')\nmetrics=evaluate_intent_model(model,CSV/'chatbot_test_set.csv')\nprint('Held-out accuracy:',round(metrics['accuracy'],4))\ndisplay(pd.DataFrame(metrics['report']).T)\nfig,ax=plt.subplots(figsize=(15,13)); disp=ConfusionMatrixDisplay(metrics['confusion_matrix'],display_labels=metrics['labels']); disp.plot(ax=ax,xticks_rotation=90,colorbar=False); plt.title('Chatbot intent confusion matrix'); plt.tight_layout(); plt.show()\npd.DataFrame(metrics['report']).T.to_csv(ROOT/'reports/phase2/chatbot_classification_report.csv')"),
('m','## Error analysis\n\nReview the most confused intent pairs, especially policy intents with similar wording, private-data requests, out-of-scope and chit-chat. Confidence threshold is a safety control, not a substitute for policy checks. The model must never decide authorization.'),
('c',"pred=pd.DataFrame({'text':test.text,'expected_intent':test.expected_intent,'predicted_intent':metrics['predictions']})\nerrors=pred[pred.expected_intent!=pred.predicted_intent]\ndisplay(errors.head(30)); errors.to_csv(ROOT/'reports/phase2/chatbot_misclassifications.csv',index=False)"),
]),
('15_chatbot_faq_slots_permissions_ui.ipynb','Task 10 — FAQ, slots, permissions and dialogue tests',[
('m','# 15 · Dialogue state, access control and FAQ\n\nValidate month extraction, follow-up memory, ambiguous/missing slots, duplicate-name disambiguation, allowed roles, safe fallback, and explicit denial for `salary_of_other`. Chit-chat must not call a private-data service. The chat endpoint is served by the FastAPI service (POST /v1/chat).'),
('c',"from pathlib import Path\nimport sys,pandas as pd\nROOT=Path.cwd()\nwhile ROOT != ROOT.parent and not (ROOT/'03_Data'/'csv').exists(): ROOT=ROOT.parent\nsys.path.insert(0,str(ROOT/'src'))\nfrom cortexhr.phase2.chatbot import train_intent_model,HRChatbot\nCSV=ROOT/'03_Data'/'csv'; bot=HRChatbot(train_intent_model(CSV/'chatbot_nlu_training.csv'),CSV/'chatbot_responses.csv',CSV/'hr_faq.csv')\nfor msg in ['hello','how many casual leaves do I get?','what is Priya Nair salary','and last month?','asdkjhasdkjhasd']:\n    result=bot.reply(msg,session_id='notebook-session',user_role='EMPLOYEE')\n    print('USER:',msg,'\\nBOT:',result['reply'],'\\nINTENT:',result['intent'],'CONF:',round(result['confidence'],3),'SLOTS:',result['slots'],'SERVICE:',result['service_called'],'\\n')"),
('c',"dialogues=pd.read_csv(CSV/'chatbot_dialogues.csv')\nprint('Official dialogue IDs:',dialogues.dialogue_id.nunique(),'| turns:',len(dialogues))\n# Re-run each dialogue in isolated session state; report predicted vs expected intent.\nrows=[]\nfor did,g in dialogues.groupby('dialogue_id',sort=True):\n    bot.reset(did)\n    for _,r in g.sort_values('turn_no').iterrows():\n        res=bot.reply(r.text,session_id=did,user_role=str(r.user_role).upper())\n        rows.append({'dialogue_id':did,'turn_no':r.turn_no,'text':r.text,'expected_intent':r.expected_intent,'predicted_intent':res['intent'],'intent_match':str(r.expected_intent)==res['intent'],'reply':res['reply'],'service_called':res['service_called']})\nresults=pd.DataFrame(rows); display(results); results.to_csv(ROOT/'reports/phase2/chatbot_dialogue_results.csv',index=False)\nprint('Turn-level intent match:',round(results.intent_match.mean(),3))"),
('m','## Try the chatbot over HTTP\n\nStart the mock HR service (port 9000) and the API (port 8000), then call `POST /v1/chat` with curl, as shown in the README. The demo uses synthetic data and does not call a real HR system.'),
])]
for name,title,cells in notebooks:
 nb=nbf.v4.new_notebook(); nb.metadata={'kernelspec':{'display_name':'Python 3','language':'python','name':'python3'},'language_info':{'name':'python','version':'3.11+'}}
 nb.cells=[]
 for typ,src in cells: nb.cells.append(md(src) if typ=='m' else code(src))
 nbf.write(nb,OUT/name)
print('Wrote',len(notebooks),'notebooks to',OUT)
